wgsl:
// The RDP's span stage for one mode, as a compute shader (a faster road, a trial; docs/parts/SPEED.md,
// section 19). The mode is line 0 of core/rdp_modes.h: one cycle, a 16-bit colour image, a 16-bit RGBA
// tile filtered from three texels in perspective, texel times shade, anti-aliased, depth compared and
// updated, opaque surface, magic-square dither. Every rule is the core's (core/rdp_pixel.c, core/rdp_tex.c,
// core/rdp_span.c; docs/parts/RDP.md, sections 5 to 9), written here for this mode alone; a tool holds
// what this leaves in memory to what the core's own loop leaves, byte for byte (tools/card-check.mjs).
//
// Two lines more are the same mode without its texture (section 21): lines 13 and 18, whose colour is the
// shade alone and whose combined alpha is the shade's (13) or the environment colour's (18). A call's head
// says which line it is (word 56). Such a call samples no texel and leaves the pipe's texel as it was.
// And line 37 is the mode with another combiner (section 22): (texel - shade) * the texel's alpha + shade for
// colour, the environment colour's alpha for the combined alpha.
// And line 8 is the mode with another second other-modes word (section 26): no depth compared or written, no
// anti-aliasing, the image in memory not read, the blender forced. Its pixel is written where its corner sample is
// covered, as it is, with full coverage; it leaves the pipe's colour from memory and
// the blender's two shifts as they were.
// And the mode as a decal (section 30; word 56 of its head is 101): the mode with another second other-modes word, which
// has no line of the core's modes: depth mode 3 (a pixel is written where it lies within reach of the depth in memory on
// both sides and that depth is not the far end), the coverage stored wrapped (its own added to memory's, three bits
// kept), no depth written.
// And a fill of a 16-bit image (word 56 of its head is 100, word 57 the fill colour): a place takes the half of the
// fill colour its word's number picks, with the hidden bits that half's lowest bit says; nothing of the pipe.
//
// One invocation is one 16-bit word's place in the colour image, counted from the image's first word
// (the RDP's pixel index). It takes the colour word and the depth word of its place, walks the spans
// that may reach the place in the order they were drawn, runs the pixel for each that does, and writes
// the two words back once. Nothing a pixel of this mode reads is left by another pixel of its call but
// those two words, so the order of the primitives at every place is the list's order. What a call leaves
// besides memory (the count of pixels written, the hidden bits last written, the pipe's words) is said in
// 64 words of its own, so that the core's drawing state is what its own loop would have left (section 20).
//
// A word of main memory is kept as its sixteen bits with the byte of the hidden bits' plane above them
// (4 and the two bits once the RDP has written the word; 0 while they follow the word's lowest bit).
// All arithmetic is in 32-bit integers that wrap, as WGSL defines them.
//
// A shader for some kinds of call only (section 29): on some cards the lines that only line 8 or a fill needs slow
// every pixel, those of the other lines too. So a host makes a text of its own for a set of kinds from this one
// (shared/card.mjs, shaderFor): a line that ends in a mark of two strokes, a wave and a kind's bit (2 line 8, 32 a
// fill, 64 the decal) is left out of a text for a set without that kind, or, where the mark goes on with an equals sign, becomes
// what follows the sign. A dispatch is drawn by the text of the smallest set that holds all its calls' kinds.

struct Params {
  first: u32,       // the first place of the dispatch
  bin: u32,         // places a bin
  count: u32,       // places
  ram_words: u32,   // 16-bit words of main memory that answer
  color_base: u32,  // the colour image's first word
  z_base: u32,      // the depth image's first word
  wrong: u32,       // a copy made wrong on purpose (tools/card-check.mjs --prove): 0 for the true shader
  bin_base: u32,    // the dispatch's first bin
  last: u32,        // the number of the last pixel of the pass's last call that is not a fill: the pixel whose words the pipe keeps
  variant: u32,     // for a reading only (the pictures' page). Parts of the work left out, a bit each: 1 nothing is said of what calls leave, 2 no texel is read from texture memory, 4 a place only walks its list, 8 nothing at all; bits 4 to 7 a number: the pixel's work ends behind its coverage (1), depth test (2), texel (3), combiner (4), blender and dither (5). What is drawn is then not the core's. And two that draw the core's pixels another way: 256 the tables from a buffer, 1,024 the texel and the colour worked for a pixel that is not written too.
  texel_last: u32,  // one more than the number of the last pixel of the pass's last call that has a texel; 0 when no call of the pass has one
  memory_last: u32, // likewise of the pass's last call that reads the image in memory
}

@group(0) @binding(0) var<uniform> P: Params;
@group(0) @binding(1) var<storage, read_write> ram: array<u32>;
@group(0) @binding(2) var<storage, read> jobs: array<u32>;    // 64 words a call (core/rdp_card.h); word 14 is its texture memory's number
@group(0) @binding(3) var<storage, read> spans: array<u32>;   // 24 words a line; word 21 is its call's number
@group(0) @binding(4) var<storage, read> bins: array<u32>;    // for each bin: where its spans begin in the list, and how many
@group(0) @binding(5) var<storage, read> list: array<u32>;    // span numbers, bin by bin, in drawing order
@group(0) @binding(6) var<storage, read> tmem: array<u32>;    // 1,024 words for each texture memory, the first byte highest
// What the calls leave besides memory (core/rdp_card.h): 0 pixels written; 1 to 8 the hidden bits last written at each
// place of a group of eight words, as the pixel's number plus one, times four, plus the bits, the highest winning;
// 9 the blender's inverse alpha in the same way, times 256; 10 one once the last pixel has been reached, and from 15
// what that pixel leaves in the pipe; 35 one once the last pixel of a call with a texel has been reached, and 11 to 14
// the texel it leaves there; 36 one once the last pixel of a call that reads the image in memory has been reached, and
// 28 to 30 and 32 and 33 the colour from memory and the two shifts it leaves there. A pixel's number counts the pixels of the pass in drawing order (a line's
// word 22 is its first pixel's), so the highest number is the pixel a processor would have drawn last.
@group(0) @binding(7) var<storage, read_write> leavings: array<atomic<u32>, 64>;

const RECIPROCAL = array<i32, 65>(
  16384, 16132, 15888, 15650, 15420, 15197, 14979, 14769, 14564, 14364, 14170, 13981, 13797,
  13618, 13443, 13273, 13107, 12945, 12788, 12633, 12483, 12336, 12193, 12053, 11916, 11782,
  11651, 11523, 11398, 11275, 11155, 11038, 10923, 10810, 10700, 10592, 10486, 10382, 10280,
  10180, 10082, 9986, 9892, 9800, 9709, 9620, 9533, 9447, 9362, 9279, 9198, 9118,
  9039, 8962, 8886, 8812, 8738, 8666, 8595, 8525, 8456, 8389, 8322, 8257, 8192);
const MAGIC = array<i32, 16>(0, 6, 1, 7, 4, 2, 5, 3, 3, 5, 2, 4, 7, 1, 6, 0);
const DEPTH_SHIFT = array<u32, 8>(6u, 5u, 4u, 3u, 2u, 1u, 0u, 0u);
const DEPTH_BASE = array<u32, 8>(0x00000u, 0x20000u, 0x30000u, 0x38000u, 0x3C000u, 0x3E000u, 0x3F000u, 0x3F800u);

struct Tables { reciprocal: array<vec4<i32>, 17>, magic: array<vec4<i32>, 4>, depth_shift: array<vec4<u32>, 2>, depth_base: array<vec4<u32>, 2> }
@group(0) @binding(8) var<uniform> T: Tables;      // the four tables above once more, for a reading (bit 256 of the variant): some cards read a table of the text slowly
fn reciprocal_at(i: u32) -> i32 { if ((P.variant & 256u) != 0u) { return T.reciprocal[i >> 2u][i & 3u]; } return RECIPROCAL[i]; }
fn magic_at(i: u32) -> i32 { if ((P.variant & 256u) != 0u) { return T.magic[i >> 2u][i & 3u]; } return MAGIC[i]; }
fn depth_shift_at(i: u32) -> u32 { if ((P.variant & 256u) != 0u) { return T.depth_shift[i >> 2u][i & 3u]; } return DEPTH_SHIFT[i]; }
fn depth_base_at(i: u32) -> u32 { if ((P.variant & 256u) != 0u) { return T.depth_base[i >> 2u][i & 3u]; } return DEPTH_BASE[i]; }

fn ext9(v: i32) -> i32 { if ((v & 0x180) == 0x180) { return v | ~0x1FF; } return v & 0x1FF; }
fn clamp9(v0: i32) -> i32 { let v = v0 & 0x1FF; if ((v & 0x100) != 0) { if ((v & 0x80) != 0) { return 0; } return 0xFF; } return v; }
fn sign9(v: i32) -> i32 { return (v << 23u) >> 23u; }
fn sign16(v: i32) -> i32 { return (v << 16u) >> 16u; }
fn hidden_of(v: u32) -> u32 { let h = v >> 16u; if ((h & 4u) != 0u) { return h & 3u; } if ((v & 1u) != 0u) { return 3u; } return 0u; }

// ---- The perspective divide (core/rdp_tex.c) ----
fn reciprocal(w0: u32) -> u32 {
  let w = w0 & 0x7FFFu;
  var shift = 14u;
  if (w != 0u) { shift = countLeadingZeros(w) - 17u; }
  let norm = (w << shift) & 0x3FFFu;
  let i = norm >> 8u;
  let along = i32((norm & 0xFFu) << 2u);
  let here = reciprocal_at(i);
  let rise = reciprocal_at(i + 1u) - here;
  let r = u32(((rise * along) >> 10u) + here) & 0x7FFFu;
  return shift | (r << 4u);
}

fn divide_one(v: i32, rcp: i32, shift: u32, range: i32, w_not_positive: bool) -> i32 {
  var product = v * rcp;
  let outside = product & range;
  var value: i32;
  if (shift != 14u) { product = product >> (13u - shift); value = product; } else { value = product << 1u; }
  var mark = 0;
  if (outside != range && outside != 0) { if ((product & 0x20000000) != 0) { mark = 0x20000; } else { mark = 0x40000; } }
  if (w_not_positive) { mark |= 0x40000; }
  return (value & 0x1FFFF) | mark;
}

fn hold16(v: i32) -> i32 {
  if ((v & 0x40000) != 0) { return 0x7FFF; }
  if ((v & 0x20000) != 0) { return 0x8000; }
  let top = v & 0x18000;
  if (top == 0x8000) { return 0x7FFF; }
  if (top == 0x10000) { return 0x8000; }
  return v & 0xFFFF;
}

// ---- A tile's shift, clamp, mirror and mask (core/rdp_tex.c) ----
fn tile_shift(coord: i32, shift: u32) -> i32 {
  if (shift < 11u) { return sign16(coord) >> shift; }
  return sign16(coord << (16u - shift));
}

struct Axis { coord: i32, frac: i32, step: i32 }

fn tile_axis(v: i32, clamp_on: bool, past: bool, last_texel: i32, mask: u32, mirror: bool, t_axis: bool) -> Axis {
  var a: Axis;
  a.frac = v & 0x1F;
  var c: i32;
  if (!clamp_on) { c = v >> 5u; }
  else if (past) { a.frac = 0; c = last_texel; }
  else if ((v & 0x10000) == 0) { c = v >> 5u; }
  else { a.frac = 0; c = 0; }
  if (mask == 0u) { a.step = 1; a.coord = c; return a; }
  let bits = i32((0xFFFFu >> (16u - mask)) & 0x3FFu);
  if (mirror) {
    let turned = (c >> min(mask, 10u)) & 1;
    c = (c ^ (-turned)) & bits;
    if (((c - turned) & bits) == bits) { a.step = 0; } else { a.step = 1 - (turned << 1u); }
  } else {
    c = c & bits;
    if (c == bits) { if (t_axis) { a.step = -(c & 0xFF); } else { a.step = -c; } } else { a.step = 1; }
  }
  a.coord = c;
  return a;
}

fn tmem_word(slot: u32, w0: u32) -> u32 {
  if ((P.variant & 2u) != 0u) { return w0 & 0xFFFFu; }
  let w = w0 & 0x7FFu;
  let u = tmem[slot * 1024u + (w >> 1u)];
  if ((w & 1u) == 0u) { return u >> 16u; }
  return u & 0xFFFFu;
}

// One texel of a 16-bit RGBA tile.
fn texel(slot: u32, line: u32, at: u32, s: i32, row: u32) -> vec4<i32> {
  let base = line * row + at;
  var w = (base << 2u) + bitcast<u32>(s);
  if ((row & 1u) != 0u) { w = w ^ 2u; }
  let v = tmem_word(slot, w);
  let r = v >> 11u; let g = (v >> 6u) & 31u; let b = (v >> 1u) & 31u;
  var a = 0;
  if ((v & 1u) != 0u) { a = 0xFF; }
  return vec4<i32>(i32((r << 3u) | (r >> 2u)), i32((g << 3u) | (g >> 2u)), i32((b << 3u) | (b >> 2u)), a);
}

// ---- Depth (core/rdp_pixel.c) ----
fn depth_pack(z0: u32) -> u32 {
  let z = z0 & 0x3FFFFu;
  let ones = min(countLeadingZeros(~(z << 14u)), 7u);
  var body: u32;
  if (ones < 5u) { body = z >> (4u - ones); } else if (ones < 6u) { body = z << 1u; } else { body = z << 2u; }
  return (body & 0x1FFCu) | (ones << 13u);
}
fn depth_unpack(word: u32) -> u32 {
  let e = (word >> 13u) & 7u;
  let body = (word >> 2u) & 0x7FFu;
  return ((body << depth_shift_at(e)) + depth_base_at(e)) & 0x3FFFFu;
}
fn depth_step_pack(v: u32) -> u32 {
  var r = 0u;
  if ((v & 0xFF00u) != 0u) { r |= 8u; }
  if ((v & 0xF0F0u) != 0u) { r |= 4u; }
  if ((v & 0xCCCCu) != 0u) { r |= 2u; }
  if ((v & 0xAAAAu) != 0u) { r |= 1u; }
  return r;
}
fn top_bit_of(v0: u32) -> u32 {
  let v = v0 & 0xFFFFu;
  if (v == 0u) { return 0u; }
  return 0x80000000u >> countLeadingZeros(v);
}

// The divider that normalises a blend on an edge pixel.
fn blend_divide(divisor4: u32, n11: u32) -> i32 {
  let d = divisor4 & 0xFu;
  let inv = (~d) & 0xFu;
  var result = 0u;
  var keep = (inv + (n11 >> 8u) + 1u) & 7u;
  for (var k = 0u; k < 8u; k++) {
    let bit = (n11 >> (7u - k)) & 1u;
    var t: u32;
    if ((result & (0x100u >> k)) != 0u) { t = inv + (keep << 1u) + bit + 1u; } else { t = d + (keep << 1u) + bit; }
    keep = t & 7u;
    if ((t & 0x10u) != 0u) { result |= 1u << (7u - k); }
  }
  return i32(result);
}

// One of a line's eight values at a place: where the span starts, and as many steps as the place is along it.
fn value_at(j: u32, s: u32, i: u32, left: bool, along: u32) -> u32 {
  var inc = jobs[j + 16u + i];
  if (!left) { inc = 0u - inc; }
  return spans[s + 13u + i] + inc * along;
}

fn columns_left_of(edge: i32) -> u32 { return u32(((edge & 7) + 1) >> 1u); }

@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  let g = gid.x;
  if (g >= P.count) { return; }
  if ((P.variant & 8u) != 0u) { return; }
  let bin = P.bin_base + g / P.bin;
  let from_at = bins[2u * bin];
  let many = bins[2u * bin + 1u];
  if (many == 0u) { return; }
  let index = P.first + g;
  let color_at = P.color_base + index;
  let z_at = P.z_base + index;
  let color_there = color_at < P.ram_words;
  let z_there = z_at < P.ram_words;
  var cw = 0u;
  var zw = 0u;
  if (color_there) { cw = ram[color_at]; }
  if (z_there) { zw = ram[z_at]; }
  var color_new = false;
  var z_new = false;
  var wrote = 0u;
  var remembered_last = 0u;     // of this place's pixels, the one with the highest number: its number plus one, times four, plus its bits
  var inverse_last = 0u;        // and of those that were blended, likewise times 256, plus the inverse alpha

  for (var k = 0u; k < many; k++) {
    let s = list[from_at + k] * 24u;
    let j = spans[s + 21u] * 64u;
    let line = spans[s];
    let x = bitcast<i32>(index - jobs[j + 8u] * line);
    let left = jobs[j + 4u] != 0u;
    let lx = bitcast<i32>(spans[s + 1u]);
    let rx = bitcast<i32>(spans[s + 2u]);
    var x_from = lx; var x_to = rx;
    if (left) { x_from = rx; x_to = lx; }
    if (x < x_from || x > x_to) { continue; }
    if ((P.variant & 4u) != 0u) { cw += 1u; color_new = true; continue; }

    // ---- A fill: the half of the fill colour that the word's number picks ----      //~32
    if (jobs[j + 56u] == 100u) {      //~32
      var along_fill = bitcast<u32>(rx - x);      //~32
      if (left) { along_fill = bitcast<u32>(x - rx); }      //~32
      let fill_color = jobs[j + 57u];      //~32
      var half = fill_color >> 16u;      //~32
      if ((color_at & 1u) != 0u) { half = fill_color & 0xFFFFu; }      //~32
      var hidden_fill = 0u;      //~32
      if ((half & 1u) != 0u) { hidden_fill = 3u; }      //~32
      if (P.wrong == 12u) { hidden_fill = 3u; }                                                                         // made wrong on purpose: every word of a fill is given full hidden bits, whatever its lowest bit      //~32
      if (color_there) { cw = half | ((4u | hidden_fill) << 16u); color_new = true; }      //~32
      wrote += 1u;      //~32
      remembered_last = max(remembered_last, ((spans[s + 22u] + along_fill + 1u) << 2u) | hidden_fill);      //~32
      continue;      //~32
    }      //~32

    // ---- Coverage: eight samples, two on each of the four sub-lines ----
    var mask = 0xFFu;
    let no_line = spans[s + 12u];
    for (var sub = 0u; sub < 4u; sub++) {
      let columns = 0xAu >> (sub & 1u);
      var up = 0u;
      if (sub < 2u) { up = 4u; }
      let these = columns << up;
      if (((no_line >> sub) & 1u) != 0u) { mask &= ~these; continue; }
      var left_edge = bitcast<i32>(spans[s + 8u + sub]);
      var right_edge = bitcast<i32>(spans[s + 4u + sub]);
      if (left) { let e = left_edge; left_edge = right_edge; right_edge = e; }
      let lp = left_edge >> 3u;
      let rp = right_edge >> 3u;
      if (x <= lp) { mask &= ~these; }
      if (x >= rp) { mask &= ~these; }
      let right_part = (0xF0u >> columns_left_of(right_edge)) & columns;
      let left_part = (0xFu >> columns_left_of(left_edge)) & columns;
      if (rp > lp) {
        if (x == rp) { mask |= right_part << up; }
        if (x == lp) { mask |= left_part << up; }
      } else if (rp == lp && x == lp) { mask |= (right_part & left_part) << up; }
    }
    mask &= 0xFFu;
    let cover = countOneBits(mask);
    var at_x = 0; var at_y = 0;
    if ((mask & 0xA0u) != 0u) { at_y = 0; if ((mask & 0x80u) != 0u) { at_x = 0; } else { at_x = 2; } }
    else if ((mask & 0x50u) != 0u) { at_y = 1; if ((mask & 0x40u) != 0u) { at_x = 1; } else { at_x = 3; } }
    else if ((mask & 0x0Au) != 0u) { at_y = 2; if ((mask & 0x08u) != 0u) { at_x = 0; } else { at_x = 2; } }
    else if ((mask & 0x05u) != 0u) { at_y = 3; if ((mask & 0x04u) != 0u) { at_x = 1; } else { at_x = 3; } }

    // ---- How far the place is along the span (value_at works each of the eight values from it) ----
    var along: u32;
    var skipped: i32;
    let unscissored = bitcast<i32>(spans[s + 3u]);
    if (left) { along = bitcast<u32>(x - rx); skipped = rx - unscissored; } else { along = bitcast<u32>(rx - x); skipped = unscissored - rx; }
    let number = spans[s + 22u] + along;
    if (skipped != 0) { along += bitcast<u32>(skipped & 0xFFF); }
    if (((P.variant >> 4u) & 15u) == 1u) { cw += 1u; color_new = true; continue; }      // (a reading: the pixel's work ends here, behind the coverage)

    // ---- Depth at the covered spot ----
    var zi = bitcast<i32>((value_at(j, s, 7u, left, along) >> 10u) & 0x3FFFFFu);
    if (cover == 8u) { zi = zi >> 3u; }
    else { zi = bitcast<i32>((bitcast<u32>(zi) << 2u) + bitcast<u32>(at_x * bitcast<i32>(jobs[j + 31u]) + at_y * bitcast<i32>(jobs[j + 39u]))) >> 5u; }
    var z: u32;
    let z_top = (zi >> 17u) & 3;
    if (z_top == 2) { z = 0x3FFFFu; } else if (z_top == 3) { z = 0u; } else { z = bitcast<u32>(zi) & 0x3FFFFu; }
    var pixel_a = i32(cover << 5u);
    if (pixel_a > 0xFF) { pixel_a = 0xFF; }
    let made = jobs[j + 56u];             // the call's line of core/rdp_modes.h: 0, 8 or 37, or 13 or 18, which have no texel
    let plain = made == 8u;               // line 8: no depth, no image read, the blender forced      //~2=    const plain = false;
    let decal = made == 101u;             // the mode as a decal      //~64=    const decal = false;

    // ---- The colour in memory ----
    let cv = cw & 0xFFFFu;
    let color_format = jobs[j + 10u];
    var memory: vec3<i32>;
    var memory_cover: u32;
    if (color_format == 0u) {
      memory = vec3<i32>(i32((cv >> 8u) & 0xF8u), i32((cv & 0x7C0u) >> 3u), i32((cv & 0x3Eu) << 2u));
      memory_cover = ((cv & 1u) << 2u) | hidden_of(cw);
    } else {
      memory = vec3<i32>(i32(cv >> 8u));
      memory_cover = (cv >> 5u) & 7u;
    }
    if (plain) { memory_cover = 7u; }     // (the image is not read: its coverage counts as full)      //~2
    if (P.wrong == 2u && color_format == 0u) { memory_cover = (cv & 1u) << 2u; }                                      // made wrong on purpose: the hidden bits are not read with the coverage
    let memory_a = i32(memory_cover << 5u);

    // ---- The depth test ----
    let dz_step = jobs[j + 12u];
    let step_code = depth_step_pack(dz_step);
    let wrapped = ((memory_cover + cover) & 8u) != 0u;
    let zv = zw & 0xFFFFu;
    let old_z = depth_unpack(zv);
    var old_code = i32(((zv & 3u) << 2u) | hidden_of(zw));
    if (plain) { old_code = 15; }         // (no depth is compared: the depth step read is left as fifteen)      //~2
    var old_step = 1u << u32(old_code);
    let shift_a = u32(clamp(i32(step_code) - old_code, 0, 4));
    let shift_b = u32(clamp(old_code - i32(step_code), 0, 4));
    var coplanar = false;
    let coarse = (zv >> 13u) & 7u;
    if (coarse < 3u) {
      if (old_step != 0x8000u) { old_step = max(old_step << 1u, 16u >> coarse); }
      else { coplanar = true; old_step = 0xFFFFu; }
    }
    let reach = top_bit_of((dz_step | old_step) & 0xFFFFu) << 3u;
    let farther = coplanar || (z + reach >= old_z);
    let in_front = z < old_z;
    let nearer = coplanar || (i32(z) - i32(reach) <= i32(old_z));
    let at_far_end = old_z == 0x3FFFFu;
    var blended = !wrapped && farther;
    var write = at_far_end;
    if (wrapped) { write = write || in_front; } else { write = write || nearer; }
    if (decal) { write = farther && nearer && !at_far_end; }      // (depth mode 3: within reach on both sides, and not at the far end)      //~64
    if (plain) { blended = true; write = (mask & 0x80u) != 0u; }      // (always blended, and written where the pixel's own corner sample is covered)      //~2
    if (plain && P.wrong == 11u) { write = cover != 0u; }                                                              // made wrong on purpose: a pixel of line 8 is written where any of its samples is covered      //~2
    if (P.wrong == 3u) { write = at_far_end || in_front; }                                                               // made wrong on purpose: an edge's pixel is tested as a wrapped one
    // The coverage the pixel leaves, written or not: its two low bits are the hidden bits remembered at its place of the group.
    var stored: u32;
    if (blended) { stored = cover + memory_cover; } else { stored = cover - 1u; }
    if ((stored & 8u) != 0u) { stored = 7u; } else { stored = stored & 7u; }
    if (decal && P.wrong != 14u) { stored = (cover + memory_cover) & 7u; }      // (the coverage stored wrapped; 14, made wrong on purpose: a decal's coverage is stored as the mode's, held at seven)      //~64
    if (P.wrong == 4u && !blended) { stored = min(cover, 7u); }                                                        // made wrong on purpose: the coverage a pixel that is not blended leaves is not one less than its own
    var remembered = 0u;
    if (color_format == 0u) { remembered = stored & 3u; }
    if (P.wrong == 6u && !(write && cover != 0u)) { remembered = 0u; }                                                 // made wrong on purpose: a pixel that is not written leaves no hidden bits remembered
    remembered_last = max(remembered_last, ((number + 1u) << 2u) | remembered);
    if (((P.variant >> 4u) & 15u) == 2u) { cw += 1u; color_new = true; continue; }      // (a reading: the pixel's work ends here, behind the depth test)
    // A pixel that will not be written, and is not the pass's last, has left all it leaves: its texel, shade and colour are not worked.
    // (A reading can ask for them to be worked all the same: bit 1,024.)
    // The colour from memory and the two shifts the pipe keeps are those of the last pixel of the last call that reads the image.
    if (number + 1u == P.memory_last && !plain && (P.variant & 1u) == 0u) {
      atomicStore(&leavings[36], 1u);
      for (var ch = 0u; ch < 3u; ch++) { atomicStore(&leavings[28u + ch], bitcast<u32>(memory[ch])); }
      atomicStore(&leavings[32], shift_a); atomicStore(&leavings[33], shift_b);
    }
    let rejected = !write || cover == 0u;
    let textured = made == 0u || made == 8u || made == 37u || decal;
    var texel_kept = textured && number + 1u == P.texel_last;      // this pixel's texel is the one the pipe keeps
    if (P.wrong == 9u) { texel_kept = number == P.last; }                                                                 // made wrong on purpose: the texel the pipe keeps is taken from the pass's last pixel, whether its call has a texel or not
    if (rejected && number != P.last && !texel_kept && (P.variant & 1024u) == 0u) { continue; }

    // ---- The texel: the point in perspective, held to 16 bits, then three of four texels ----
    var texel0 = vec4<i32>(0);
    if (textured) {
    let w_top = bitcast<i32>(value_at(j, s, 6u, left, along)) >> 16u;
    let packed = reciprocal(bitcast<u32>(w_top));
    let shift = packed & 15u;
    let range = bitcast<i32>(0x3FFFFFFFu & (0u - (0x20000000u >> shift)));
    let w_not_positive = sign16(w_top) <= 0;
    var ts = hold16(divide_one(sign16(bitcast<i32>(value_at(j, s, 4u, left, along)) >> 16u), i32(packed >> 4u), shift, range, w_not_positive));
    var tt = hold16(divide_one(sign16(bitcast<i32>(value_at(j, s, 5u, left, along)) >> 16u), i32(packed >> 4u), shift, range, w_not_positive));
    let tile = jobs[j + 40u];
    let mask_s = (tile >> 4u) & 15u;
    let mask_t = (tile >> 20u) & 15u;
    let corner_a = jobs[j + 42u];
    let corner_b = jobs[j + 43u];
    let sl = i32(corner_a & 0xFFFFu); let tl = i32(corner_a >> 16u);
    let sh = i32(corner_b & 0xFFFFu); let th = i32(corner_b >> 16u);
    ts = tile_shift(ts, (tile >> 8u) & 15u);
    tt = tile_shift(tt, (tile >> 24u) & 15u);
    let past_s = (ts >> 3u) >= sh;
    let past_t = (tt >> 3u) >= th;
    ts -= sl << 3u;
    tt -= tl << 3u;
    let ax = tile_axis(ts, (tile & 1u) != 0u || mask_s == 0u, past_s, ((sh >> 2u) - (sl >> 2u)) & 0x3FF, mask_s, ((tile >> 1u) & 1u) != 0u, false);
    let ay = tile_axis(tt, ((tile >> 16u) & 1u) != 0u || mask_t == 0u, past_t, ((th >> 2u) - (tl >> 2u)) & 0x3FF, mask_t, ((tile >> 17u) & 1u) != 0u, true);
    let slot = jobs[j + 14u];
    let tile_line = jobs[j + 41u] & 0xFFFFu;
    let tile_at = jobs[j + 41u] >> 16u;
    let row0 = bitcast<u32>(ay.coord) & 0xFFu;
    let row1 = row0 + bitcast<u32>(ay.step);
    let c0 = texel(slot, tile_line, tile_at, ax.coord, row0);
    let c1 = texel(slot, tile_line, tile_at, ax.coord + ax.step, row0);
    let c2 = texel(slot, tile_line, tile_at, ax.coord, row1);
    let c3 = texel(slot, tile_line, tile_at, ax.coord + ax.step, row1);
    if (((ax.frac + ay.frac) & 0x20) != 0) {
      texel0 = c3 + (((0x20 - ax.frac) * (c2 - c3) + (0x20 - ay.frac) * (c1 - c3) + vec4<i32>(0x10)) >> vec4<u32>(5u));
    } else {
      texel0 = c0 + ((ax.frac * (c1 - c0) + ay.frac * (c2 - c0) + vec4<i32>(0x10)) >> vec4<u32>(5u));
    }
    texel0 = texel0 & vec4<i32>(0x1FF);
    }
    if (texel_kept && (P.variant & 1u) == 0u) {
      atomicStore(&leavings[35], 1u);
      for (var ch = 0u; ch < 4u; ch++) { atomicStore(&leavings[11u + ch], bitcast<u32>(texel0[ch])); }
    }
    if (((P.variant >> 4u) & 15u) == 3u) { cw += 1u; color_new = true; continue; }      // (a reading: the pixel's work ends here, behind the texel)

    // ---- Shade at the covered spot ----
    var shade: vec4<i32>;
    for (var i = 0u; i < 4u; i++) {
      var v = bitcast<i32>(value_at(j, s, i, left, along)) >> 14u;
      if (cover == 8u) { v = v >> 2u; }
      else { v = bitcast<i32>((bitcast<u32>(v) << 2u) + bitcast<u32>(at_x * bitcast<i32>(jobs[j + 24u + i]) + at_y * bitcast<i32>(jobs[j + 32u + i]))) >> 4u; }
      shade[i] = clamp9(v);
    }

    if (plain) { pixel_a = shade[3]; }    // (the pixel's alpha is the combined alpha, not its coverage)      //~2

    // ---- The combiner: texel times shade for colour, shade for alpha; the pixel's alpha is its coverage ----
    // (A line without a texel: (0 - 0) * 0 + shade, which is the shade as it is; its alpha the shade's, or for line 18 the environment colour's.)
    var pixel: vec3<i32>;
    var combined: vec3<i32>;
    var combined_a = shade[3];
    if (made == 37u && P.wrong != 10u) {                                                                                 // (10, made wrong on purpose: a call of line 37 is combined as one of line 0)
      // (texel - shade) * the texel's alpha + shade: A, B and D count 0x180 and above as negative, C is a plain signed nine bits.
      for (var ch = 0u; ch < 3u; ch++) {
        let rgb = bitcast<i32>(bitcast<u32>((ext9(texel0[ch]) - ext9(shade[ch])) * sign9(texel0[3])) + (bitcast<u32>(ext9(shade[ch])) << 8u) + 0x80u) & 0x1FFFF;
        combined[ch] = rgb >> 8u;
        pixel[ch] = clamp9(rgb >> 8u);
      }
      combined_a = bitcast<i32>(jobs[j + 50u] & 0xFFu);
    } else if (textured || P.wrong == 7u) {                                                                              // (7, made wrong on purpose: a call without a texel has its shade multiplied by a texel all the same)
      for (var ch = 0u; ch < 3u; ch++) {
        let rgb = bitcast<i32>(bitcast<u32>(ext9(texel0[ch]) * sign9(shade[ch])) + 0x80u) & 0x1FFFF;
        combined[ch] = rgb >> 8u;
        pixel[ch] = clamp9(rgb >> 8u);
      }
    } else {
      for (var ch = 0u; ch < 3u; ch++) { combined[ch] = shade[ch]; pixel[ch] = shade[ch]; }
      if (made == 18u && P.wrong != 8u) { combined_a = bitcast<i32>(jobs[j + 50u] & 0xFFu); }                              // (8, made wrong on purpose: line 18's combined alpha is the shade's)
    }
    if (P.wrong == 1u && made == 0u) { pixel[1] = clamp9(bitcast<i32>(bitcast<u32>(ext9(texel0[1]) * sign9(shade[1]))) >> 8u); }      // made wrong on purpose: the combiner does not round
    if (((P.variant >> 4u) & 15u) == 4u) { cw += 1u; color_new = true; continue; }      // (a reading: the pixel's work ends here, behind the combiner)
    if (number == P.last && (P.variant & 1u) == 0u) {
      atomicStore(&leavings[10], 1u);
      for (var ch = 0u; ch < 4u; ch++) { atomicStore(&leavings[15u + ch], bitcast<u32>(shade[ch])); }
      for (var ch = 0u; ch < 3u; ch++) {
        atomicStore(&leavings[19u + ch], bitcast<u32>(combined[ch]));
        atomicStore(&leavings[23u + ch], bitcast<u32>(pixel[ch]));
      }
      atomicStore(&leavings[22], bitcast<u32>(combined_a)); atomicStore(&leavings[26], bitcast<u32>(pixel_a)); atomicStore(&leavings[27], bitcast<u32>(shade[3]));
      atomicStore(&leavings[31], bitcast<u32>(memory_a)); atomicStore(&leavings[34], bitcast<u32>(old_code));
    }
    if (rejected) { continue; }
    wrote += 1u;

    // ---- The blender: the pixel as it is, or weighed against memory by the two coverages on an edge ----
    var res = pixel;
    // (Line 8: the blend forced, pixel against pixel with the weights nought and one: pixel * 0 + pixel * 32, its top eight
    // bits, which is the pixel; the inverse alpha left is that of the nought.)
    if (plain) { inverse_last = max(inverse_last, ((number + 1u) << 8u) | 0xFFu); }      //~2
    if (blended && !plain) {
      inverse_last = max(inverse_last, ((number + 1u) << 8u) | (bitcast<u32>(~pixel_a) & 0xFFu));
      let a = (u32(pixel_a >> 3u) >> shift_a) & 0x3Cu;
      let b = (u32(memory_a >> 3u) >> shift_b) | 3u;
      let divisor = ((a & ~3u) + (b & ~3u) + 4u) >> 2u;
      for (var ch = 0u; ch < 3u; ch++) {
        let sum = bitcast<u32>(pixel[ch] * i32(a) + memory[ch] * i32(b + 1u));
        res[ch] = blend_divide(divisor, (sum >> 2u) & 0x7FFu);
      }
    }

    // ---- Dither by the magic square ----
    let dither = magic_at((((line >> (jobs[j + 11u] & 31u)) & 3u) << 2u) | (bitcast<u32>(x) & 3u));
    for (var ch = 0u; ch < 3u; ch++) {
      let v = res[ch];
      if (dither < (v & 7)) { if (v > 247) { res[ch] = 255; } else { res[ch] = (v & 0xF8) + 8; } }
    }
    if (((P.variant >> 4u) & 15u) == 5u) { cw += 1u; color_new = true; continue; }      // (a reading: the pixel's work ends here, behind the blender and the dither)

    // ---- The write: colour with the coverage it leaves, and depth with its step ----
    let r = bitcast<u32>(res[0]); let gr = bitcast<u32>(res[1]); let bl = bitcast<u32>(res[2]);
    if (color_there) {
      if (color_format == 0u) { cw = ((((r & ~7u) << 8u) | ((gr & ~7u) << 3u) | ((bl & ~7u) >> 2u) | (stored >> 2u)) & 0xFFFFu) | ((4u | (stored & 3u)) << 16u); }
      else { cw = (((r << 8u) | (stored << 5u)) & 0xFFFFu) | (4u << 16u); }
      color_new = true;
    }
    if (z_there && !plain && !decal) {
      zw = ((depth_pack(z) | (step_code >> 2u)) & 0xFFFFu) | ((4u | (step_code & 3u)) << 16u);
      z_new = true;
    }
  }

  if (color_new) { ram[color_at] = cw; }
  if (z_new) { ram[z_at] = zw; }
  // What this place's pixels leave besides memory: said once, behind the place's last line (a place's words are in one
  // of the eight places of a group, so all its pixels speak for the same one).
  if ((P.variant & 1u) != 0u) { return; }
  if (wrote != 0u) { atomicAdd(&leavings[0], wrote); }
  if (remembered_last != 0u) { atomicMax(&leavings[1u + (color_at & 7u)], remembered_last); }
  if (inverse_last != 0u) { atomicMax(&leavings[9], inverse_last); }
}
